#include <stdint.h>
#include <stdlib.h>
#include <string.h>

struct field {
  uint8_t tag;
  uint8_t len;
  uint8_t *val;
};

/* Parse one tag/length/value entry into a field with a 16-byte value slot. */
int parse_field(const uint8_t *in, size_t n, struct field *f) {
  if (n < 2) return -1;
  f->tag = in[0];
  f->len = in[1];
  if (n - 2 < f->len) return -1;
  f->val = malloc(16);
  if (!f->val) return -1;
  memcpy(f->val, in + 2, f->len);
  return 0;
}

