/* Apply (index, value) pairs from a file section onto a slot table. */
extern "C" size_t apply_pairs(std::vector<uint32_t> &slot, const uint8_t *p, size_t n) {
  size_t done = 0;
  for (size_t off = 0; n - off >= 8; off += 8) {
    uint32_t idx, val;
    memcpy(&idx, p + off, 4);
    memcpy(&val, p + off + 4, 4);
    if (val == 0) continue;
    slot[idx] = val;
    done++;
  }
  return done;
}

