/* Expand (count, byte) pairs into a fresh buffer of cap bytes. */
uint8_t *rle_expand(const uint8_t *in, size_t n, size_t cap, size_t *out_len) {
  uint8_t *out = malloc(cap ? cap : 1);
  size_t pos = 0;
  if (!out) return NULL;
  for (size_t i = 0; i + 1 < n; i += 2) {
    size_t run = in[i];
    memset(out + pos, in[i + 1], run);
    pos += run;
  }
  *out_len = pos;
  return out;
}

