#include <stdint.h>
#include <stdlib.h>

#define MAP_CAP 16

struct slot {
  uint32_t key;
  uint32_t val;
};

/* Open-addressing insert into the heap table of MAP_CAP slots built by the caller; the probe mask is read from the stream header. */
int map_put(struct slot *tab, uint32_t mask, uint32_t key, uint32_t val) {
  uint32_t i = key & mask;
  for (int probes = 0; probes < MAP_CAP; probes++) {
    if (tab[i].key == 0) {
      tab[i].key = key;
      tab[i].val = val;
      return 0;
    }
    i = (i + 1) & mask;
  }
  return -1;
}

