static size_t get_varint(const uint8_t *p, size_t n, uint32_t *out) {
  uint32_t v = 0;
  for (size_t i = 0; i < n && i < 5; i++) {
    v |= (uint32_t)(p[i] & 0x7f) << (7 * i);
    if (!(p[i] & 0x80)) { *out = v; return i + 1; }
  }
  return 0;
}

/* Copy the encoded dims of a varint shape (rank byte first) and fold them. */
int shape_sum(const uint8_t *p, size_t n, uint64_t *sum) {
  uint8_t enc[16];
  uint8_t *w = enc;
  size_t used = 1;
  if (n < 1) return -1;
  *sum = 0;
  for (size_t k = 0; k < p[0]; k++) {
    uint32_t v;
    size_t c = get_varint(p + used, n - used, &v);
    if (c == 0) return -1;
    memcpy(w, p + used, c);
    w += c;
    used += c;
    *sum += v;
  }
  for (uint8_t *r = enc; r != w; r++) *sum += *r;
  return 0;
}

