/* Append successor nodes and count them on the last pre-existing node. */
extern "C" int link_successors(std::vector<Node> &nodes, const int *ids, size_t count) {
  if (nodes.empty()) return -1;
  Node *prev = &nodes.back();
  for (size_t i = 0; i < count; i++) {
    nodes.push_back(Node{ids[i], 0});
    prev->fanout += 1;
  }
  return prev->fanout;
}

