#include <stdint.h>
#include <stdlib.h>
#include <string.h>

struct hdr {
  uint32_t total;
  uint32_t kind;
};

struct pkt {
  uint8_t *buf;
  size_t used, cap;
};

/* Append a payload to a packet whose first bytes hold a header. */
int pkt_append(struct pkt *p, const uint8_t *data, size_t n) {
  struct hdr *h = (struct hdr *)p->buf;
  if (p->used < sizeof(struct hdr) || n > SIZE_MAX - p->used) return -1;
  if (p->used + n > p->cap) {
    uint8_t *grown = realloc(p->buf, p->used + n);
    if (!grown) return -1;
    p->buf = grown;
    p->cap = p->used + n;
  }
  memcpy(p->buf + p->used, data, n);
  p->used += n;
  h->total += (uint32_t)n;
  return 0;
}

