#include <stdlib.h>

struct session {
  size_t bytes;
  size_t limit;
  void (*on_limit)(struct session *);
};

static void drop_session(struct session *s) { free(s); }

struct session *session_new(size_t limit) {
  struct session *s = calloc(1, sizeof *s);
  if (!s) return NULL;
  s->limit = limit;
  s->on_limit = drop_session;
  return s;
}

/* Account for n received bytes; the limit callback releases the session. */
size_t session_feed(struct session *s, size_t n) {
  s->bytes += n;
  if (s->bytes >= s->limit) s->on_limit(s);
  return s->bytes;
}

