#include <stdlib.h>
#include <string.h>

struct node { char *name; struct node *next; };

static int push_name(struct node **head, char *name) {
  struct node *nd = malloc(sizeof *nd);
  if (nd == NULL) return -1;
  nd->name = name;
  nd->next = *head;
  *head = nd;
  return 0;
}

/* Register a copy of src; the list owns the copy once it is pushed. */
int add_name(struct node **head, const char *src) {
  char *copy = strdup(src);
  if (copy == NULL) return -1;
  if (push_name(head, copy) != 0) { free(copy); return -1; }
  if (strlen(copy) > 32) { free(copy); return -2; }
  return 0;
}

void drop_names(struct node *head) {
  while (head != NULL) {
    struct node *next = head->next;
    free(head->name);
    free(head);
    head = next;
  }
}

