class Scratch {
 public:
  explicit Scratch(size_t cap) : buf_(new unsigned char[cap ? cap : 1]), cap_(cap) {}
  ~Scratch() { delete[] buf_; }
  Scratch(const Scratch &) = delete;
  Scratch &operator=(const Scratch &) = delete;
  size_t cap() const { return cap_; }
  unsigned char *data() { return buf_; }
  /* Drop the storage once a record is fully decoded. */
  void release() {
    delete[] buf_;
    cap_ = 0;
  }
 private:
  unsigned char *buf_;
  size_t cap_;
};

size_t decode_run(Scratch &s, const unsigned char *in, size_t n, bool last) {
  size_t take = n < s.cap() ? n : s.cap();
  if (take > 0) memcpy(s.data(), in, take);
  size_t sum = 0;
  for (size_t i = 0; i < take; i++) sum += s.data()[i];
  if (last) s.release();
  return sum;
}

