struct Header { uint32_t magic = 0; uint32_t count = 0; uint16_t flags = 0; };

static uint32_t le32(const uint8_t *p) {
  return (uint32_t)p[0] | (uint32_t)p[1] << 8 | (uint32_t)p[2] << 16 | (uint32_t)p[3] << 24;
}

static bool read_header(Header *h, const uint8_t *p, size_t n) {
  if (n < 10) { delete h; return false; }
  h->magic = le32(p);
  h->count = le32(p + 4);
  h->flags = (uint16_t)(p[8] | p[9] << 8);
  return h->magic == 0x46445548u;
}

/* Parse a 10-byte header; the caller owns the result. */
extern "C" Header *load_header(const uint8_t *p, size_t n) {
  Header *h = new Header();
  if (!read_header(h, p, n)) { delete h; return nullptr; }
  return h;
}

