enum { T_LEAF = 0, T_PAIR = 1 };

struct Node {
  virtual ~Node() {}
  virtual long value() const { return 0; }
};
struct Leaf : Node {
  long val = 0;
  long value() const override { return val; }
};
struct Pair : Node {
  const Node *l = nullptr;
  int l_tag = T_LEAF; /* tag of the left child as read from the stream */
};

/* Descend the left spine of a decoded tree; tag is the stream tag of n. */
long leftmost(const Node *n, int tag) {
  while (tag == T_PAIR) {
    if (!n) return -1;
    const Pair *p = static_cast<const Pair *>(n);
    n = p->l;
    tag = p->l_tag;
  }
  return n ? n->value() : -1;
}

