/* Count atoms in an S-expression; *pp advances past the form that was read. */
static long sexp_atoms(const char **pp, const char *end) {
  long total = 0;
  while (*pp < end && **pp != ')') {
    if (**pp == '(') {
      (*pp)++;
      total += sexp_atoms(pp, end);
      if (*pp < end) (*pp)++;
    } else if (**pp == ' ') {
      (*pp)++;
    } else {
      total++;
      while (*pp < end && **pp != ' ' && **pp != '(' && **pp != ')') (*pp)++;
    }
  }
  return total;
}

long count_atoms(const char *s, size_t n) {
  const char *p = s;
  return sexp_atoms(&p, s + n);
}

