class Calc {
 public:
  explicit Calc(const std::string &s) : s_(s) {}
  bool run(uint64_t *out) { *out = expr(0); return pos_ == s_.size(); }

 private:
  const std::string &s_;
  size_t pos_ = 0;
  char peek() const { return pos_ < s_.size() ? s_[pos_] : '\0'; }
  uint64_t atom() {
    if (peek() == '(') {
      pos_++;
      uint64_t v = expr(0);
      if (peek() == ')') pos_++;
      return v;
    }
    uint64_t v = 0;
    while (peek() >= '0' && peek() <= '9') v = v * 10 + (uint64_t)(s_[pos_++] - '0');
    return v;
  }
  uint64_t expr(int level) {
    if (level == 2) return atom();
    uint64_t v = expr(level + 1);
    char op = level == 0 ? '+' : '*';
    while (peek() == op) {
      pos_++;
      uint64_t r = expr(level + 1);
      v = level == 0 ? v + r : v * r;
    }
    return v;
  }
};

