struct Expr {
  int op; /* '+', '*', or 0 for a literal */
  uint64_t lit;
  const Expr *l;
  const Expr *r;
};

/* Evaluate a decoded expression tree. */
extern "C" int fold_expr(const Expr *e, uint64_t *out) {
  if (!e) return -1;
  if (e->op == 0) {
