/* Count the items in one bencoded value at *p; -1 when it is malformed. */
static long bdecode(const unsigned char **p, const unsigned char *end) {
  if (*p >= end) return -1;
  unsigned char c = *(*p)++;
  if (c == 'i') {
    while (*p < end && **p != 'e') (*p)++;
    if (*p >= end) return -1;
    (*p)++;
    return 1;
  }
  if (c != 'l') return -1;
  long n = 1;
  while (*p < end && **p != 'e') {
    long k = bdecode(p, end);
    if (k < 0) return -1;
    n += k;
  }
  if (*p >= end) return -1;
  (*p)++;
  return n;
}

long count_items(const unsigned char *buf, size_t n) {
  const unsigned char *p = buf;
  return bdecode(&p, buf + n);
}

