    if (!lenNDV) {
      blend_vec[master] = 0;
      continue;
    }
    int32_t scalar = 0x10000;
    for (uint32_t axis = 0; axis < vs->axisCount; ++axis) {
      if (varRegion->axisList[axis] > ndv[axis]) scalar = 0;
    }
    blend_vec[master] = scalar;
  }
  return 0;
}

