struct SnappyInputBuffer {
  size_t output_buffer_capacity_;
  std::unique_ptr<char[]> output_buffer_;
  size_t avail_out_ = 0;

  int Inflate(const char* block, size_t uncompressed_length) {
    assert(output_buffer_capacity_ >= uncompressed_length);
